const update = $json ?? {};

// Según la versión/configuración del Telegram Trigger,
// n8n puede entregar el update completo o directamente el mensaje.
const message =
  update.message ??
  update.edited_message ??
  update.channel_post ??
  update.edited_channel_post ??
  update;

const raw = String(message.text ?? message.caption ?? '');

function normalizar(texto) {
  return String(texto ?? '')
    .normalize('NFD')
    .replace(/\p{Diacritic}/gu, '')
    .toLowerCase()
    .trim()
    .replace(/[.,;:!?¿¡"'()]/g, '')
    .replace(/\s+/g, ' ');
}

return [{
  json: {
    update_id: String(
      update.update_id ??
      message.update_id ??
      `${message.chat?.id ?? 'sin-chat'}-${message.message_id ?? Date.now()}`
    ),
    chat_id: String(message.chat?.id ?? ''),
    user_id: String(message.from?.id ?? ''),
    nombre_usuario: String(message.from?.first_name ?? ''),
    texto_original: raw,
    texto: normalizar(raw),
    recibido_en: new Date().toISOString()
  }
}];

// Leemos el mensaje directamente desde Telegram Trigger para no depender
// de que los nodos intermedios conserven todos los campos.
const trigger = $('Telegram Trigger').first()?.json ?? {};

const telegramMessage =
  trigger.message ??
  trigger.edited_message ??
  trigger.channel_post ??
  trigger.edited_channel_post ??
  trigger.body?.message ??
  trigger.body ??
  trigger;

function normalizar(texto) {
  return String(texto ?? '')
    .normalize('NFD')
    .replace(/\p{Diacritic}/gu, '')
    .toLowerCase()
    .trim()
    .replace(/[.,;:!?¿¡"'()]/g, '')
    .replace(/\s+/g, ' ');
}

const rawText = String(
  telegramMessage.text ??
  telegramMessage.caption ??
  ''
);

const msg = {
  update_id: String(
    trigger.update_id ??
    trigger.body?.update_id ??
    telegramMessage.update_id ??
    ''
  ),
  chat_id: String(telegramMessage.chat?.id ?? ''),
  user_id: String(telegramMessage.from?.id ?? ''),
  nombre_usuario: String(telegramMessage.from?.first_name ?? ''),
  texto_original: rawText,
  text: normalizar(rawText),
  recibido_en: new Date().toISOString()
};

// El nodo Firestore puede devolver un documento, un objeto vacío o incluso
// conservar datos de entrada. Solo lo consideramos equipo si tiene estado.
const candidate = $json ?? {};
const existing =
  typeof candidate === 'object' &&
  candidate !== null &&
  typeof candidate.estado === 'string'
    ? candidate
    : null;

const now = new Date().toISOString();

let team = existing ? {...existing} : null;
let action = '';
let response = '';
let needsStation = false;

const isStart = msg.text === '/start' || msg.text.startsWith('/start ');

if (!team) {
  if (isStart) {
    team = {
      id: msg.chat_id,
      chat_id: msg.chat_id,
      nombre: '',
      estado: 'pendiente_nombre',
      estacion_actual: 1,
      inicio: '',
      fin: '',
      pistas_usadas: 0,
      mapas_usados: 0,
      penalizacion_minutos: 0,
      fragmentos: '',
      pista_actual: 0,
      mapa_estaciones: '',
      intentos: 0,
      actualizado_en: now
    };
    action = 'save_send';
    response = '📜 Bienvenidos a El Linaje Olvidado.\n\nEscribid ahora el nombre de vuestro equipo.';
  } else {
    action = 'send_only';
    response = `Para comenzar la gymkana, enviad /start\n\n[DEBUG texto recibido: "${msg.text}"]`;
  }
} else if (team.estado === 'pendiente_nombre') {
  team.nombre = msg.texto_original.trim().slice(0, 80) || 'Equipo sin nombre';
  team.estado = 'en_juego';
  team.inicio = now;
  team.actualizado_en = now;
  action = 'save_send';
  response = `📜 EL CÓDICE DEL LINAJE OLVIDADO

Bienvenidos, ${team.nombre}. El reloj empieza ahora.

📍 PARADA 1 — Parque del Conde de la Revilla-Gigante

Dirigíos a la zona verde de la entrada principal de la villa, donde los caminos se cruzan antes de entrar en el casco empedrado.

🧩 PRIMER ACERTIJO

Buscad el monolito de piedra con la bienvenida oficial a la villa. Contad el número exacto de letras que componen la primera palabra labrada en el texto principal.

¿Cuál es ese número?

Podéis responder directamente o escribir PISTA, MAPA, REPETIR o ESTADO.`;
} else if (team.estado === 'finalizado') {
  if (msg.text === 'rescate' || msg.text === '/rescate') {
    action = 'final_summary';
  } else {
    action = 'send_only';
    response = '🏆 Este equipo ya ha finalizado la gymkana. Escribid RESCATE si queréis volver a ver el resumen y la ubicación final.';
  }
} else if (isStart) {
  action = 'send_only';
  response = `La partida de ${team.nombre} ya está en curso. Escribid ESTADO para consultar el progreso.`;
} else if (msg.text === 'estado' || msg.text === '/estado') {
  action = 'send_only';
  response = `📜 ESTADO DEL EQUIPO\n\nEquipo: ${team.nombre}\nEstación: ${team.estacion_actual} de 8\nFragmentos: ${team.fragmentos || '(ninguno)'}\nPistas: ${team.pistas_usadas}\nMapas: ${team.mapas_usados}\nPenalización: ${team.penalizacion_minutos} min`;
} else {
  action = 'station';
  needsStation = true;
}

return [{json:{msg,team,action,response,needsStation}}];

const ctx = $('Decidir acción').first().json;
const team = {...ctx.team};
const msg = ctx.msg;
const station = $json;
const now = new Date().toISOString();

function norm(s) {
  return String(s ?? '')
    .normalize('NFD').replace(/\p{Diacritic}/gu,'')
    .toLowerCase().trim()
    .replace(/[.,;:!?¿¡"'()]/g,'')
    .replace(/\s+/g,' ');
}

let response = '';
let changed = false;

if (msg.text === 'pista' || msg.text === '/pista') {
  const current = Number(team.pista_actual || 0);
  if (current >= 3) {
    response = 'Ya habéis utilizado las tres pistas de esta estación. Escribid RESCATE si queréis la solución de esta parada y avanzar (+3 min), o MAPA si solo queréis una pista visual (+3 min).';
  } else {
    const next = current + 1;
    response = `💡 Pista ${next}: ${station['pista'+next]}`;
    if (next >= 3) {
      response += '\n\n⚠️ Has agotado las 3 pistas de esta parada. Si no lográis dar con la respuesta, podéis usar el comando /rescate para obtener la solución y avanzar (+3 min de penalización).';
    }
    team.pista_actual = next;
    team.pistas_usadas = Number(team.pistas_usadas || 0) + 1;
    changed = true;
  }
} else if (msg.text === 'mapa' || msg.text === '/mapa') {
  const used = String(team.mapa_estaciones || '').split(',').filter(Boolean);
  const key = String(team.estacion_actual);
  if (!used.includes(key)) {
    used.push(key);
    team.mapa_estaciones = used.join(',');
    team.mapas_usados = Number(team.mapas_usados || 0) + 1;
    team.penalizacion_minutos = Number(team.penalizacion_minutos || 0) + 3;
    changed = true;
    response = `📍 Pista de mapa (+3 min): ${station.mapa_url}`;
  } else {
    response = `📍 Ya habíais solicitado este mapa: ${station.mapa_url}`;
  }
} else if (msg.text === 'rescate' || msg.text === '/rescate') {
  const fragment = String(station.fragmento || '');
  if (fragment) {
    team.fragmentos = `${team.fragmentos || ''}${fragment}`;
  }
  team.penalizacion_minutos = Number(team.penalizacion_minutos || 0) + 3;
  changed = true;

  if (Number(team.estacion_actual) >= 8) {
    team.estado = 'finalizado';
    team.fin = now;
    const startMs = new Date(team.inicio).getTime();
    const elapsed = Number.isFinite(startMs) ? Math.floor((Date.now()-startMs)/1000) : 0;
    const finalSeconds = elapsed + Number(team.penalizacion_minutos || 0)*60;
    const fmt = s => `${Math.floor(s/60)} min ${s%60} s`;
    response = `🆘 Rescate final (+3 min)\n\n${station.capsula}\n\n⏱ Tiempo real: ${fmt(elapsed)}\n💡 Pistas: ${team.pistas_usadas}\n📍 Mapas: ${team.mapas_usados}\n⏳ Penalización: ${team.penalizacion_minutos} min\n🏆 Tiempo final: ${fmt(finalSeconds)}`;
  } else {
    team.estacion_actual = Number(team.estacion_actual) + 1;
    team.pista_actual = 0;
    response = `🆘 Rescate (+3 min)\n\n${station.capsula}\n\nFragmentos: ${team.fragmentos}\n\n${station.siguiente}`;
  }
} else if (msg.text === 'repetir' || msg.text === '/repetir') {
  response = `📍 Estación ${station.orden}: ${station.nombre}\n\n🧩 ${station.acertijo}`;
} else {
  const accepted = String(station.respuestas || '').split('|').map(norm);
  if (accepted.includes(msg.text)) {
    const fragment = String(station.fragmento || '');
    if (fragment) {
      team.fragmentos = `${team.fragmentos || ''}${fragment}`;
    }

    if (Number(team.estacion_actual) >= 8) {
      team.estado = 'finalizado';
      team.fin = now;
      const startMs = new Date(team.inicio).getTime();
      const elapsed = Number.isFinite(startMs) ? Math.floor((Date.now()-startMs)/1000) : 0;
      const finalSeconds = elapsed + Number(team.penalizacion_minutos || 0)*60;
      const fmt = s => `${Math.floor(s/60)} min ${s%60} s`;
      response = `${station.capsula}\n\n⏱ Tiempo real: ${fmt(elapsed)}\n💡 Pistas: ${team.pistas_usadas}\n📍 Mapas: ${team.mapas_usados}\n⏳ Penalización: ${team.penalizacion_minutos} min\n🏆 Tiempo final: ${fmt(finalSeconds)}`;
    } else {
      team.estacion_actual = Number(team.estacion_actual) + 1;
      team.pista_actual = 0;
      response = `✅ ¡Respuesta correcta!\n\n${station.capsula}\n\nFragmentos: ${team.fragmentos}\n\n${station.siguiente}`;
    }
    changed = true;
  } else {
    team.intentos = Number(team.intentos || 0) + 1;
    changed = true;
    response = '❌ Esa respuesta no es correcta. Observad de nuevo o escribid PISTA.';
  }
}

team.actualizado_en = now;
return [{json:{...team,response,chat_id:msg.chat_id,changed}}];

